import sys

# Check if MemPalace directory exists
mempalace_dir = os.path.expanduser('~/.hermes/mempalace')
print(f"Checking MemPalace directory: {mempalace_dir}")
print(f"Directory exists: {os.path.exists(mempalace_dir)}")

if os.path.exists(mempalace_dir):
    # List subdirectories
    subdirs = ['raw', 'semantic', 'episodic', 'procedural', 'preferences', 'indexes', 'palace']
    for subdir in subdirs:
        path = os.path.join(mempalace_dir, subdir)
        exists = os.path.exists(path)
        count = 0
        if exists and os.path.isdir(path):
            try:
                count = len([f for f in os.listdir(path) if not f.startswith('.')])
            except:
                count = "error"
        print(f"  {subdir}: {'✓' if exists else '✗'} ({count} files)")

    # Check for scripts directory
    scripts_dir = os.path.join(mempalace_dir, 'scripts')
    scripts_exist = os.path.exists(scripts_dir)
    print(f"  scripts: {'✓' if scripts_exist else '✗'}")
    if scripts_exist:
        try:
            scripts = [f for f in os.listdir(scripts_dir) if f.endswith('.py') or f.endswith('.sh')]
            print(f"    Scripts: {scripts}")
        except:
            print(f"    Could not list scripts")
else:
    print("MemPalace directory does not exist. Need to initialize.")"}

