    try:
        with open(id_map_path, 'r') as f:
            id_map = json.load(f)
        print(f"ID map loaded successfully")
        print(f"  Entries: {len(id_map)}")
        # Show first few entries as sample
        sample = dict(list(id_map.items())[:5]) if len(id_map) > 0 else {}
