{"code": "import os
import sys
import subprocess

mempalace_dir = os.path.expanduser('~/.hermes/mempalace')
scripts_dir = os.path.join(mempalace_dir, 'scripts')

print("=== Available Maintenance Scripts ===")
if os.path.exists(scripts_dir):
    scripts = [f for f in os.listdir(scripts_dir) if f.endswith('.py') or f.endswith('.sh')]
    for script in sorted(scripts):
        print(f"  {script}")
else:
    print("Scripts directory not found")

print("\n=== Running Cron Maintenance ===")
# Try to run the cron_maintenance.py script
cron_maintenance = os.path.join(scripts_dir, 'cron_maintenance.py')
if os.path.exists(cron_maintenance):
    try:
        result = subprocess.run([sys.executable, cron_maintenance], 
                                capture_output=True, text=True, timeout=60)
        print("Exit code:", result.returncode)
        if result.stdout:
            print("STDOUT:")
            print(result.stdout)
        if result.stderr:
            print("STDERR:")
            print(result.stderr)
    except subprocess.TimeoutExpired:
        print("Maintenance script timed out after 60 seconds")
    except Exception as e:
        print(f"Error running maintenance script: {e}")
else:
    print("cron_maintenance.py not found")
    # Try maintenance.sh
    maintenance_sh = os.path.join(scripts_dir, 'maintenance.sh')
    if os.path.exists(maintenance_sh):
        try:
            result = subprocess.run(['bash', maintenance_sh], 
                                    capture_output=True, text=True, timeout=60)
            print("Exit code:", result.returncode)
            if result.stdout:
                print("STDOUT:")
                print(result.stdout)
            if result.stderr:
                print("STDERR:")
                print(result.stderr)
        except subprocess.TimeoutExpired:
            print("Maintenance script timed out after 60 seconds")
        except Exception as e:
            print(f"Error running maintenance script: {e}")
    else:
        print("No maintenance script found")"}

